"""Configuration for SafeHER AI/ML Modules."""

from dataclasses import dataclass
from typing import Optional


MANDATORY_AI_DISCLAIMER = (
    "DISCLAIMER: This automated preliminary assessment is generated by an assistive AI system "
    "for organizational and informational triage only. It does not constitute legal, medical, "
    "or digital forensic proof. Automated scores reflect pattern detection heuristics and "
    "preliminary signals that must be independently reviewed by authorized human professionals. "
    "If you or someone you know is in immediate physical danger, contact emergency services "
    "or local law enforcement authorities immediately."
)


@dataclass
class ThreatAnalyzerConfig:
    """Configuration settings for threat assessment analyzers."""

    max_input_length: int = 10000
    min_input_length: int = 1
    device: str = "cpu"
    batch_size: int = 16
    enable_toxicity_check: bool = False
    model_name_or_path: Optional[str] = None
    is_development_placeholder: bool = True


default_ai_config = ThreatAnalyzerConfig()
